# EXOTIC's own fits of its single-transit and multiple-transit examples, on seeded data, for
# test/exotic.test.mjs. The data are generated by EXOTIC's transit() exactly as the example
# scripts do (examples/single_transit/transit_fit_example.py, examples/multiple_transit/
# multi_fit_example.py) and stored with EXOTIC's posterior so ESL can fit the same numbers.
#   /Users/kpearson/miniconda3/envs/exotic/bin/python test/make_exotic_fits.py [single|multiple|all]
# Writes test/exotic_fits.json (merging with what is already there).
import json, os, sys, time, warnings
import numpy as np
warnings.filterwarnings('ignore')
import exotic
from exotic.api.elca import transit, lc_fitter, glc_fitter
which = sys.argv[1] if len(sys.argv) > 1 else 'all'
path = 'test/exotic_fits.json'
out = json.load(open(path)) if os.path.exists(path) else {}
out['generator'] = f'EXOTIC {exotic.__version__}'

if which in ('single', 'all'):
    np.random.seed(7)
    prior = {'rprs': 0.02, 'ars': 14.25, 'per': 3.33, 'inc': 88.5, 'ecc': 0.5, 'omega': 120, 'tmid': 0.75, 'a1': 50, 'a2': 0.,
             'T*': 5000, 'FE/H': 0, 'LOGG': 3.89}
    from pylightcurve import exotethys
    u = exotethys(prior['LOGG'], prior['T*'], prior['FE/H'], 'TESS', method='claret', stellar_model='phoenix')
    for i in range(4): prior[f'u{i}'] = float(u[i])
    t = np.linspace(0.7, 0.8, 1000); airmass = np.zeros(len(t))
    data = transit(t, prior) * prior['a1'] * np.exp(prior['a2'] * airmass)
    data += np.random.normal(0, prior['a1'] * 250e-6, len(t))
    # the example draws error bars of about 6e-4 in units where the flux is 50, far below the 1.25e-2 scatter;
    # here they are set to the injected scatter so chi2 means something (the example's own values are kept alongside)
    err_example = np.random.normal(300e-6, 50e-6, len(t)) + np.random.normal(300e-6, 50e-6, len(t))
    err = np.full(len(t), prior['a1'] * 250e-6)
    bounds = {'rprs': [0, 0.1], 'tmid': [prior['tmid'] - 0.01, prior['tmid'] + 0.01], 'inc': [87, 90]}
    t0 = time.time(); fit = lc_fitter(t, data, err, airmass, prior, bounds, mode='ns')
    out['single'] = {'prior': {k: float(v) for k, v in prior.items()}, 'bounds': bounds, 't': t.tolist(), 'flux': data.tolist(), 'err': err.tolist(),
                     'err_example_mean': float(err_example.mean()),
                     'parameters': {k: float(fit.parameters[k]) for k in bounds}, 'errors': {k: float(fit.errors[k]) for k in bounds},
                     'posterior_mean': {k: float(fit.results['posterior']['mean'][i]) for i, k in enumerate(fit.results['paramnames'])},
                     'logz': float(fit.results['logz']), 'logzerr': float(fit.results['logzerr']), 'ncall': int(fit.results['ncall']), 'seconds': time.time() - t0}
    json.dump(out, open(path, 'w')); print('single done', out['single']['parameters'], out['single']['errors'], round(time.time() - t0), 's')

if which in ('multiple', 'all'):
    np.random.seed(11)
    epochs = np.sort(np.random.choice(np.arange(100), 5, replace=False))     # the example uses 8; 5 keeps EXOTIC's run to minutes
    input_data, local_bounds, sets = [], [], []
    for epoch in epochs:
        nobs = np.random.randint(50) + 100
        phase = np.linspace(-0.02 - 0.01 * np.random.random(), 0.02 + 0.01 * np.random.random(), nobs)
        prior = {'rprs': 0.1, 'ars': 14.25, 'per': 3.5, 'inc': 88.0, 'u0': 1.349, 'u1': -0.709, 'u2': 0.362, 'u3': -0.087, 'ecc': 0, 'omega': 0, 'tmid': 1,
                 'a1': 5000 + 2500 * np.random.random(), 'a2': -0.25 + 0.1 * np.random.random()}
        tt = prior['tmid'] + prior['per'] * (phase + epoch); st = tt - tt[0]
        airmass = 1. / np.cos(np.deg2rad(90 - 90 * np.cos(4 * st - np.pi / 6)))
        model = transit(tt, prior) * prior['a1'] * np.exp(prior['a2'] * airmass)
        flux = model * np.random.normal(1, np.mean(np.sqrt(model) / model) * 0.25, model.shape)
        ferr = flux ** 0.5 * 0.25                                                # the example passes flux**0.5, four times the injected scatter
        input_data.append({'time': tt, 'flux': flux, 'ferr': ferr, 'airmass': airmass, 'priors': prior})
        local_bounds.append({'a2': [-0.75, 0.25]})
        sets.append({'epoch': int(epoch), 'a1': prior['a1'], 'a2': prior['a2'], 't': tt.tolist(), 'flux': flux.tolist(), 'err': ferr.tolist(), 'airmass': airmass.tolist()})
    gb = {'rprs': [0, 0.2], 'per': [3.5 - 0.001, 3.5 + 0.001], 'tmid': [1 - 0.01, 1 + 0.01], 'inc': [87, 90]}
    t0 = time.time(); fit = glc_fitter(input_data, gb, local_bounds, individual_fit=False, verbose=False)
    out['multiple'] = {'truth': {'rprs': 0.1, 'ars': 14.25, 'per': 3.5, 'inc': 88.0, 'tmid': 1, 'ld': [1.349, -0.709, 0.362, -0.087]}, 'bounds': gb, 'local_bounds': {'a2': [-0.75, 0.25]},
                       'sets': sets, 'parameters': {k: float(v) for k, v in fit.parameters.items() if np.isscalar(v)}, 'errors': {k: float(v) for k, v in fit.errors.items() if np.isscalar(v)},
                       'paramnames': list(fit.results['paramnames']), 'posterior_mean': [float(x) for x in fit.results['posterior']['mean']], 'posterior_stdev': [float(x) for x in fit.results['posterior']['stdev']],
                       'logz': float(fit.results['logz']), 'logzerr': float(fit.results['logzerr']), 'ncall': int(fit.results['ncall']), 'seconds': time.time() - t0}
    json.dump(out, open(path, 'w')); print('multiple done', {k: out['multiple']['parameters'][k] for k in gb}, round(time.time() - t0), 's')
